-- ==============================================================================
-- 4. Functions
-- ==============================================================================
CREATE OR REPLACE FUNCTION "sales-pipe".add_note(p_opportunity_id uuid, p_body text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'sales-pipe', 'public'
AS $function$
DECLARE v_id uuid;
BEGIN
    PERFORM "sales-pipe".check_opp_access(p_opportunity_id);
    IF coalesce(trim(p_body), '') = '' THEN RAISE EXCEPTION 'The note is empty'; END IF;
    INSERT INTO "sales-pipe".notes (opportunity_id, body, created_by)
    VALUES (p_opportunity_id, trim(p_body), auth.uid()) RETURNING id INTO v_id;
    RETURN v_id;
END;
$function$;
REVOKE ALL ON FUNCTION "sales-pipe"."add_note"(p_opportunity_id uuid, p_body text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION "sales-pipe"."add_note"(p_opportunity_id uuid, p_body text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "sales-pipe"."add_note"(p_opportunity_id uuid, p_body text) TO "service_role";

CREATE OR REPLACE FUNCTION "sales-pipe".add_opt_out(p_identifier text, p_channel text, p_reason text, p_source text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'sales-pipe', 'public'
AS $function$
DECLARE
    v_id text := nullif(trim(coalesce(p_identifier, '')), '');
    v_phone boolean := p_channel = 'WhatsApp';
BEGIN
    IF v_id IS NULL THEN RETURN false; END IF;
    IF v_phone THEN
        IF length(regexp_replace(v_id, '\D', '', 'g')) < 7 THEN RETURN false; END IF;
        v_id := "sales-pipe".normalise_phone(v_id);
    ELSE
        v_id := lower(v_id);
    END IF;
    IF EXISTS (
        SELECT 1 FROM "sales-pipe".opt_outs o
        WHERE lower(o.channel) IN ('all', lower(p_channel))
          AND CASE WHEN v_phone THEN regexp_replace(o.identifier, '\D', '', 'g') = regexp_replace(v_id, '\D', '', 'g')
                   ELSE lower(o.identifier) = v_id END
    ) THEN
        RETURN false;
    END IF;
    INSERT INTO "sales-pipe".opt_outs (identifier, channel, reason, source)
    VALUES (v_id, p_channel, left(p_reason, 300), p_source);
    RETURN true;
END;
$function$;
REVOKE ALL ON FUNCTION "sales-pipe"."add_opt_out"(p_identifier text, p_channel text, p_reason text, p_source text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION "sales-pipe"."add_opt_out"(p_identifier text, p_channel text, p_reason text, p_source text) TO "service_role";

