CREATE OR REPLACE FUNCTION "sales-pipe".trg_campaign_reply_stop_opt_out()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'sales-pipe', 'public'
AS $function$
BEGIN
    PERFORM "sales-pipe".add_opt_out(
        NEW.from_address, CASE NEW.channel WHEN 'whatsapp' THEN 'WhatsApp' ELSE 'Email' END,
        'Replied "' || left(trim(NEW.body), 40) || '" to a campaign', 'inbound');
    RETURN NULL;
END;
$function$;
GRANT EXECUTE ON FUNCTION "sales-pipe"."trg_campaign_reply_stop_opt_out"() TO PUBLIC;
GRANT EXECUTE ON FUNCTION "sales-pipe"."trg_campaign_reply_stop_opt_out"() TO "authenticated";
GRANT EXECUTE ON FUNCTION "sales-pipe"."trg_campaign_reply_stop_opt_out"() TO "service_role";

CREATE OR REPLACE FUNCTION "sales-pipe".trg_dnc_stage_opt_out()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'sales-pipe', 'public'
AS $function$
DECLARE
    b record;
BEGIN
    SELECT business_name, email, whatsapp_number INTO b FROM "sales-pipe".businesses WHERE id = NEW.business_id;
    IF NEW.stage = 'Do not contact' THEN
        PERFORM "sales-pipe".add_opt_out(b.email, 'Email', 'Lead moved to Do not contact', 'stage');
        PERFORM "sales-pipe".add_opt_out(b.whatsapp_number, 'WhatsApp', 'Lead moved to Do not contact', 'stage');
    ELSIF TG_OP = 'UPDATE' AND OLD.stage = 'Do not contact'
          AND NOT EXISTS (SELECT 1 FROM "sales-pipe".opportunities o
                          WHERE o.business_id = NEW.business_id AND o.id <> NEW.id AND o.stage = 'Do not contact') THEN
        DELETE FROM "sales-pipe".opt_outs o
        WHERE o.source = 'stage'
          AND ((lower(o.channel) = 'email' AND lower(o.identifier) = lower(trim(coalesce(b.email, ''))))
            OR (lower(o.channel) = 'whatsapp' AND length(regexp_replace(coalesce(b.whatsapp_number, ''), '\D', '', 'g')) >= 7
                AND regexp_replace(o.identifier, '\D', '', 'g') = regexp_replace("sales-pipe".normalise_phone(b.whatsapp_number), '\D', '', 'g')));
    END IF;
    RETURN NULL;
END;
$function$;
GRANT EXECUTE ON FUNCTION "sales-pipe"."trg_dnc_stage_opt_out"() TO PUBLIC;
GRANT EXECUTE ON FUNCTION "sales-pipe"."trg_dnc_stage_opt_out"() TO "authenticated";
GRANT EXECUTE ON FUNCTION "sales-pipe"."trg_dnc_stage_opt_out"() TO "service_role";

CREATE OR REPLACE FUNCTION "sales-pipe".trg_match_booking()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'sales-pipe', 'public'
AS $function$
DECLARE
    v_ids uuid[];
    v_opp record;
BEGIN
    NEW.phone_normalised := "sales-pipe".normalise_phone(NEW.phone);
    NEW.email_normalised := "sales-pipe".normalise_email(NEW.email);

    SELECT array_agg(o.id) INTO v_ids
    FROM "sales-pipe".opportunities o
    JOIN "sales-pipe".businesses b ON o.business_id = b.id
    WHERE o.stage IN ('Needs review', 'Active', 'Interested', 'Went cold', 'No response')
      AND (
        (NEW.phone_normalised IS NOT NULL AND b.phone_normalised = NEW.phone_normalised) OR
        (NEW.email_normalised IS NOT NULL AND b.email_normalised = NEW.email_normalised)
      );

    IF coalesce(array_length(v_ids, 1), 0) = 1 THEN
        SELECT * INTO v_opp FROM "sales-pipe".opportunities WHERE id = v_ids[1];
        NEW.match_status := 'matched';
        NEW.matched_opportunity_id := v_opp.id;

        UPDATE "sales-pipe".opportunities
        SET stage = 'Consultation', consultation_at = NEW.booked_for
        WHERE id = v_opp.id;

        INSERT INTO "sales-pipe".stage_changes (opportunity_id, from_stage, to_stage, reason)
        VALUES (v_opp.id, v_opp.stage, 'Consultation', 'Booked a consultation on the website');

        INSERT INTO "sales-pipe".notifications (user_id, type, title, link)
        SELECT id, 'needs_consultant', 'Consultation booked. Assign a consultant.', '/dashboard/' || v_opp.id
        FROM "sales-pipe".profiles WHERE role = 'admin' AND is_active = true;

        IF v_opp.assigned_sales_id IS NOT NULL THEN
            INSERT INTO "sales-pipe".notifications (user_id, type, title, link)
            VALUES (v_opp.assigned_sales_id, 'booking_matched', 'One of your businesses booked a consultation', '/dashboard/' || v_opp.id);
        END IF;
    ELSE
        NEW.match_status := 'unmatched';
        INSERT INTO "sales-pipe".notifications (user_id, type, title, link)
        SELECT id, 'booking_unmatched', 'New booking from ' || NEW.business_name || ' needs linking', '/dashboard'
        FROM "sales-pipe".profiles WHERE role = 'admin' AND is_active = true;
    END IF;

    RETURN NEW;
END;
$function$;
REVOKE ALL ON FUNCTION "sales-pipe"."trg_match_booking"() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION "sales-pipe"."trg_match_booking"() TO "authenticated";
GRANT EXECUTE ON FUNCTION "sales-pipe"."trg_match_booking"() TO "service_role";

CREATE OR REPLACE FUNCTION "sales-pipe".trg_message_stop_opt_out()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'sales-pipe', 'public'
AS $function$
DECLARE
    v record;
BEGIN
    SELECT t.platform, b.email, b.whatsapp_number, b.instagram, b.facebook, b.linkedin INTO v
    FROM "sales-pipe".threads t
    JOIN "sales-pipe".opportunities o ON o.id = t.opportunity_id
    JOIN "sales-pipe".businesses b ON b.id = o.business_id
    WHERE t.id = NEW.thread_id;
    IF v.platform IS NULL THEN RETURN NULL; END IF;

    PERFORM "sales-pipe".add_opt_out(
        CASE v.platform WHEN 'WhatsApp' THEN v.whatsapp_number WHEN 'Email' THEN v.email
                        WHEN 'Instagram' THEN v.instagram WHEN 'Facebook' THEN v.facebook WHEN 'LinkedIn' THEN v.linkedin END,
        v.platform, 'Replied "' || left(trim(NEW.body), 40) || '" on ' || v.platform, 'inbound');
    RETURN NULL;
END;
$function$;
GRANT EXECUTE ON FUNCTION "sales-pipe"."trg_message_stop_opt_out"() TO PUBLIC;
GRANT EXECUTE ON FUNCTION "sales-pipe"."trg_message_stop_opt_out"() TO "authenticated";
GRANT EXECUTE ON FUNCTION "sales-pipe"."trg_message_stop_opt_out"() TO "service_role";

