GRANT EXECUTE ON FUNCTION "sales-pipe"."trg_normalise_business_contact"() TO "service_role";

CREATE OR REPLACE FUNCTION "sales-pipe".trg_notification_text()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'sales-pipe', 'public'
AS $function$
DECLARE
    t record;
BEGIN
    -- Only rewrite when the creator didn't write its own message
    IF NEW.message IS NULL THEN
        t := "sales-pipe".notification_text(NEW.type, NEW.title, NEW.link);
        NEW.title := t.title;
        NEW.message := t.message;
    END IF;
    RETURN NEW;
END;
$function$;
GRANT EXECUTE ON FUNCTION "sales-pipe"."trg_notification_text"() TO PUBLIC;
GRANT EXECUTE ON FUNCTION "sales-pipe"."trg_notification_text"() TO "authenticated";
GRANT EXECUTE ON FUNCTION "sales-pipe"."trg_notification_text"() TO "service_role";

CREATE OR REPLACE FUNCTION "sales-pipe".trg_opp_reopen()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'sales-pipe', 'public'
AS $function$
DECLARE
    v_reply_thread uuid;
    v_platform text;
    t record;
BEGIN
    -- Drafts are signed with the sales person's name, so make sure there is one
    IF NEW.assigned_sales_id IS NULL THEN
        PERFORM "sales-pipe".auto_assign_sales(ARRAY[NEW.id]);
    END IF;

    -- The late reply that brought the lead back, if any
    IF OLD.replied_after_close_at IS NOT NULL THEN
        SELECT id, platform INTO v_reply_thread, v_platform FROM "sales-pipe".threads
        WHERE opportunity_id = NEW.id AND last_inbound_at >= OLD.replied_after_close_at - interval '1 minute'
        ORDER BY last_inbound_at DESC LIMIT 1;
    END IF;

    -- The new round starts just before the late reply, so that reply shows as current
    UPDATE "sales-pipe".threads
    SET round = round + 1,
        round_started_at = CASE WHEN v_reply_thread IS NOT NULL THEN OLD.replied_after_close_at - interval '1 second' ELSE now() END,
        step = 0,
        status = CASE WHEN id = v_reply_thread THEN 'Replied'
                      WHEN v_reply_thread IS NOT NULL THEN 'Paused'
                      ELSE 'Not contacted' END,
        paused_reason = CASE WHEN v_reply_thread IS NOT NULL AND id <> v_reply_thread THEN 'Replied on ' || v_platform END,
        next_due_on = CASE WHEN v_reply_thread IS NULL THEN CURRENT_DATE END
    WHERE opportunity_id = NEW.id;

    UPDATE "sales-pipe".opportunities SET replied_after_close_at = NULL, closed_at = NULL WHERE id = NEW.id;

    FOR t IN SELECT id FROM "sales-pipe".threads WHERE opportunity_id = NEW.id AND status IN ('Not contacted', 'Replied') LOOP
        PERFORM "sales-pipe".generate_draft(t.id, CASE WHEN t.id = v_reply_thread THEN 'Reply' ELSE 'First contact' END);
    END LOOP;
    RETURN NULL;
END;
$function$;
REVOKE ALL ON FUNCTION "sales-pipe"."trg_opp_reopen"() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION "sales-pipe"."trg_opp_reopen"() TO "service_role";

CREATE OR REPLACE FUNCTION "sales-pipe".trg_opp_services_recompute_problems()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'sales-pipe', 'public'
AS $function$
BEGIN
    IF TG_OP = 'UPDATE' AND OLD.services_pitched IS NOT DISTINCT FROM NEW.services_pitched THEN
        RETURN NEW;
    END IF;
    UPDATE "sales-pipe".businesses
    SET problems = "sales-pipe".lead_problems(NEW.business_id)
    WHERE id = NEW.business_id;
    RETURN NEW;
END;
$function$;
REVOKE ALL ON FUNCTION "sales-pipe"."trg_opp_services_recompute_problems"() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION "sales-pipe"."trg_opp_services_recompute_problems"() TO "authenticated";
GRANT EXECUTE ON FUNCTION "sales-pipe"."trg_opp_services_recompute_problems"() TO "service_role";

CREATE OR REPLACE FUNCTION "sales-pipe".trg_opp_stage_cleanup()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'sales-pipe', 'public'
AS $function$
BEGIN
    IF NEW.stage IS DISTINCT FROM OLD.stage
       AND NEW.stage IN ('Consultation', 'Won', 'Declined', 'Do not contact', 'No response', 'Went cold') THEN
        PERFORM "sales-pipe".discard_drafts(NEW.id);
        UPDATE "sales-pipe".threads SET next_due_on = NULL
        WHERE opportunity_id = NEW.id AND status IN ('Not contacted', 'Awaiting reply');
    END IF;
    RETURN NEW;
END;
$function$;
REVOKE ALL ON FUNCTION "sales-pipe"."trg_opp_stage_cleanup"() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION "sales-pipe"."trg_opp_stage_cleanup"() TO "authenticated";
GRANT EXECUTE ON FUNCTION "sales-pipe"."trg_opp_stage_cleanup"() TO "service_role";

CREATE OR REPLACE FUNCTION "sales-pipe".trg_sync_read_to_shared_product_notifications()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
BEGIN
    IF NEW.is_read IS DISTINCT FROM OLD.is_read AND NEW.is_read = true THEN
        UPDATE shared.product_notifications
        SET is_read = true,
            read_at = COALESCE(read_at, now())
        WHERE metadata->>'sales_notification_id' = NEW.id::text;
    END IF;
    RETURN NEW;
EXCEPTION
    WHEN OTHERS THEN
        RAISE WARNING 'trg_sync_read_to_shared_product_notifications error: %', SQLERRM;
        RETURN NEW;
END;
$function$;
GRANT EXECUTE ON FUNCTION "sales-pipe"."trg_sync_read_to_shared_product_notifications"() TO PUBLIC;
GRANT EXECUTE ON FUNCTION "sales-pipe"."trg_sync_read_to_shared_product_notifications"() TO "authenticated";
GRANT EXECUTE ON FUNCTION "sales-pipe"."trg_sync_read_to_shared_product_notifications"() TO "service_role";

CREATE OR REPLACE FUNCTION "sales-pipe".trg_sync_to_shared_product_notifications()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'sales-pipe', 'public'
AS $function$
DECLARE
    v_employee_id integer;
    v_role text;
BEGIN
    IF NEW.user_id IS NULL THEN RETURN NEW; END IF;
    SELECT e.id INTO v_employee_id
    FROM hr.employees e
    JOIN public.user_product_access upa ON upa.employee_id = e.id
    JOIN public.products p ON p.product_id = upa.product_id AND p.code = 'sales_pipeline'
    WHERE e.auth_user_id = NEW.user_id
    LIMIT 1;
    IF v_employee_id IS NULL THEN RETURN NEW; END IF;
    SELECT role INTO v_role FROM "sales-pipe".profiles WHERE id = NEW.user_id;

    INSERT INTO shared.product_notifications (product_code, title, message, type, employee_id, is_read, created_at, metadata)
    VALUES (
        'sales_pipeline',
        CASE NEW.type
            WHEN 'new_reply' THEN 'New reply'
            WHEN 'assigned_to_you' THEN 'Assigned to you'
            WHEN 'needs_consultant' THEN 'Needs a consultant'
            WHEN 'upsell_due' THEN 'Upsell due'
            WHEN 'unsubscribed' THEN 'Opted out'
            WHEN 'booking_matched' THEN 'Booking matched'
            WHEN 'booking_unmatched' THEN 'Booking not matched'
            WHEN 'consultation_reminder' THEN 'Consultation tomorrow'
            WHEN 'reply_waiting' THEN 'Reply waiting'
            ELSE 'Sales Pipeline'
        END,
        coalesce(nullif(NEW.message, ''), NEW.title),
        CASE WHEN NEW.type IN ('assigned_to_you', 'needs_consultant', 'reply_waiting') THEN 'action_required'
             WHEN NEW.type IN ('unsubscribed', 'booking_unmatched') THEN 'warning'
             ELSE 'info' END,
        v_employee_id,
        coalesce(NEW.is_read, false),
        coalesce(NEW.created_at, now()),
        jsonb_build_object('link', NEW.link, 'channel', 'in_app', 'sales_notification_id', NEW.id,
                           'sales_user_id', NEW.user_id, 'sales_type', NEW.type, 'role', v_role)
    );
    RETURN NEW;
EXCEPTION
    WHEN OTHERS THEN
        RAISE WARNING 'trg_sync_to_shared_product_notifications error: %', SQLERRM;
        RETURN NEW;
END;
$function$;
GRANT EXECUTE ON FUNCTION "sales-pipe"."trg_sync_to_shared_product_notifications"() TO PUBLIC;
GRANT EXECUTE ON FUNCTION "sales-pipe"."trg_sync_to_shared_product_notifications"() TO "authenticated";
GRANT EXECUTE ON FUNCTION "sales-pipe"."trg_sync_to_shared_product_notifications"() TO "service_role";

