CREATE OR REPLACE FUNCTION "sales-pipe".v_business_cards(p_service text, p_type text, p_filter text, p_search text, p_limit integer, p_offset integer)
 RETURNS TABLE(opportunity_id uuid, business_name text, area text, google_rating numeric, stage text, threads jsonb)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'sales-pipe', 'public'
AS $function$
declare
  v_uid uuid := auth.uid();
  v_role text := "sales-pipe".get_user_role();
begin
  return query
  select 
    o.id as opportunity_id,
    b.business_name,
    b.area,
    b.google_rating,
    o.stage,
    (
      select jsonb_agg(
        jsonb_build_object(
          'platform', t.platform,
          'status', t.status,
          'step', t.step
        )
      )
      from "sales-pipe".threads t
      where t.opportunity_id = o.id
    ) as threads
  from "sales-pipe".opportunities o
  join "sales-pipe".businesses b on b.id = o.business_id
  where (p_service = '' or p_service = any(o.services_pitched))
    and (p_type = '' or b.business_type = p_type)
    and (p_filter = 'all' or o.stage = p_filter)
    and (p_search = '' or b.business_name ilike '%' || p_search || '%')
    and (v_role = 'admin' or o.assigned_sales_id = v_uid or o.assigned_consultant_id = v_uid)
  order by o.created_at desc
  limit p_limit offset p_offset;
end;
$function$;
REVOKE ALL ON FUNCTION "sales-pipe"."v_business_cards"(p_service text, p_type text, p_filter text, p_search text, p_limit integer, p_offset integer) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION "sales-pipe"."v_business_cards"(p_service text, p_type text, p_filter text, p_search text, p_limit integer, p_offset integer) TO "authenticated";
GRANT EXECUTE ON FUNCTION "sales-pipe"."v_business_cards"(p_service text, p_type text, p_filter text, p_search text, p_limit integer, p_offset integer) TO "service_role";

CREATE OR REPLACE FUNCTION "sales-pipe".v_business_type_counts(p_service text, p_user uuid)
 RETURNS TABLE(business_type text, businesses_count bigint, replies_count bigint, due_today_count bigint)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'sales-pipe', 'public'
AS $function$
DECLARE
    v_role text;
BEGIN
    IF auth.role() <> 'service_role' AND p_user IS DISTINCT FROM auth.uid()
       AND coalesce("sales-pipe".get_user_role(), '') <> 'admin' THEN
        RAISE EXCEPTION 'You can only see your own numbers';
    END IF;
    SELECT role INTO v_role FROM "sales-pipe".profiles WHERE id = p_user;

    RETURN QUERY
    SELECT b.business_type,
        count(DISTINCT b.id),
        count(DISTINCT o.id) FILTER (WHERE o.stage IN ('Active', 'Interested', 'Consultation') AND EXISTS (
            SELECT 1 FROM "sales-pipe".threads t WHERE t.opportunity_id = o.id AND t.status = 'Replied'
              AND t.last_inbound_at > coalesce(t.last_outbound_at, '-infinity'))),
        count(DISTINCT o.id) FILTER (WHERE o.stage IN ('Active', 'Interested') AND EXISTS (
            SELECT 1 FROM "sales-pipe".threads t WHERE t.opportunity_id = o.id
              AND t.status IN ('Not contacted', 'Awaiting reply') AND t.next_due_on <= CURRENT_DATE))
    FROM "sales-pipe".opportunities o
    JOIN "sales-pipe".businesses b ON b.id = o.business_id AND NOT b.archived
    WHERE p_service = ANY(o.services_pitched)
      AND (v_role = 'admin' OR o.assigned_sales_id = p_user OR o.assigned_consultant_id = p_user
           OR (v_role IN ('sales', 'consultant', 'sales_consultant') AND o.assigned_sales_id IS NULL AND o.assigned_consultant_id IS NULL)
           OR (v_role IN ('consultant', 'sales_consultant') AND o.stage = 'Consultation'))
    GROUP BY b.business_type
    ORDER BY count(DISTINCT b.id) DESC;
END;
$function$;
REVOKE ALL ON FUNCTION "sales-pipe"."v_business_type_counts"(p_service text, p_user uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION "sales-pipe"."v_business_type_counts"(p_service text, p_user uuid) TO "authenticated";
GRANT EXECUTE ON FUNCTION "sales-pipe"."v_business_type_counts"(p_service text, p_user uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "sales-pipe".v_dashboard_status_counts(p_user uuid)
 RETURNS TABLE(needs_reply bigint, interested bigint, consultation bigint, went_cold bigint, no_response bigint, needs_consultant bigint, off_target bigint, needs_review bigint, total_pitches bigint)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'sales-pipe', 'public'
AS $function$
DECLARE
    v_role text;
BEGIN
    IF auth.role() <> 'service_role' AND p_user IS DISTINCT FROM auth.uid()
       AND coalesce("sales-pipe".get_user_role(), '') <> 'admin' THEN
        RAISE EXCEPTION 'You can only see your own numbers';
    END IF;
    SELECT role INTO v_role FROM "sales-pipe".profiles WHERE id = p_user;

    RETURN QUERY
    WITH visible AS (
        SELECT o.*, b.problems, b.off_target_at FROM "sales-pipe".opportunities o
        JOIN "sales-pipe".businesses b ON b.id = o.business_id AND NOT b.archived
        WHERE v_role = 'admin' OR o.assigned_sales_id = p_user OR o.assigned_consultant_id = p_user
           OR (v_role IN ('sales', 'consultant', 'sales_consultant') AND o.assigned_sales_id IS NULL AND o.assigned_consultant_id IS NULL)
           OR (v_role IN ('consultant', 'sales_consultant') AND o.stage = 'Consultation')
    ),
    mine AS (SELECT * FROM visible WHERE off_target_at IS NULL)
    SELECT
        (SELECT count(DISTINCT m.id) FROM mine m JOIN "sales-pipe".threads t ON t.opportunity_id = m.id
          WHERE m.stage IN ('Active', 'Interested', 'Consultation') AND t.status = 'Replied'
            AND t.last_inbound_at > coalesce(t.last_outbound_at, '-infinity')),
        (SELECT count(*) FROM mine WHERE stage = 'Interested'),
        (SELECT count(*) FROM mine WHERE stage = 'Consultation'),
        (SELECT count(*) FROM mine WHERE stage = 'Went cold'),
        (SELECT count(*) FROM mine WHERE stage = 'No response'),
        (CASE WHEN v_role = 'admin' THEN (SELECT count(*) FROM mine WHERE stage = 'Consultation' AND assigned_consultant_id IS NULL) ELSE 0 END),
        (SELECT count(DISTINCT business_id) FROM visible WHERE off_target_at IS NOT NULL),
        (SELECT count(*) FROM visible WHERE stage = 'Needs review' AND problems = '{}'::text[]),
        (SELECT count(*) FROM visible);
END;
$function$;
REVOKE ALL ON FUNCTION "sales-pipe"."v_dashboard_status_counts"(p_user uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION "sales-pipe"."v_dashboard_status_counts"(p_user uuid) TO "authenticated";
GRANT EXECUTE ON FUNCTION "sales-pipe"."v_dashboard_status_counts"(p_user uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "sales-pipe".v_due_today(p_tab text, p_limit integer DEFAULT 100, p_offset integer DEFAULT 0)
 RETURNS TABLE(thread_id uuid, opportunity_id uuid, business_name text, business_type text, platform text, step integer, status text, next_due_on date, last_inbound_at timestamp with time zone, draft_status text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'sales-pipe', 'public'
AS $function$
DECLARE
    v_uid uuid := auth.uid();
    v_role text := "sales-pipe".get_user_role();
BEGIN
    RETURN QUERY
    SELECT t.id, o.id, b.business_name, b.business_type, t.platform, t.step, t.status, t.next_due_on, t.last_inbound_at,
           (SELECT d.status FROM "sales-pipe".drafts d WHERE d.thread_id = t.id AND d.status IN ('ready', 'needs_data')
             ORDER BY d.created_at DESC LIMIT 1)
    FROM "sales-pipe".threads t
    JOIN "sales-pipe".opportunities o ON o.id = t.opportunity_id
    JOIN "sales-pipe".businesses b ON b.id = o.business_id AND NOT b.archived AND b.off_target_at IS NULL
    WHERE o.stage IN ('Active', 'Interested', 'Consultation')
      AND (v_role = 'admin' OR o.assigned_sales_id = v_uid OR o.assigned_consultant_id = v_uid)
      AND (
        (p_tab = 'New outreach' AND t.status = 'Not contacted' AND t.next_due_on <= current_date) OR
        (p_tab = 'Follow-ups'   AND t.status = 'Awaiting reply' AND t.next_due_on <= current_date AND t.step < 4) OR
        (p_tab = 'Replies'      AND t.status = 'Replied' AND t.last_inbound_at > coalesce(t.last_outbound_at, '-infinity'))
      )
    ORDER BY t.next_due_on ASC NULLS LAST, t.last_inbound_at ASC NULLS LAST
    LIMIT least(coalesce(p_limit, 100), 500) OFFSET greatest(coalesce(p_offset, 0), 0);
END;
$function$;
REVOKE ALL ON FUNCTION "sales-pipe"."v_due_today"(p_tab text, p_limit integer, p_offset integer) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION "sales-pipe"."v_due_today"(p_tab text, p_limit integer, p_offset integer) TO "authenticated";
GRANT EXECUTE ON FUNCTION "sales-pipe"."v_due_today"(p_tab text, p_limit integer, p_offset integer) TO "service_role";

CREATE OR REPLACE FUNCTION "sales-pipe".v_service_counts(p_user uuid)
 RETURNS TABLE(service_name text, businesses_count bigint, replies_count bigint, active_count bigint, won_count bigint)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'sales-pipe', 'public'
AS $function$
DECLARE
    v_role text;
BEGIN
    IF auth.role() <> 'service_role' AND p_user IS DISTINCT FROM auth.uid()
       AND coalesce("sales-pipe".get_user_role(), '') <> 'admin' THEN
        RAISE EXCEPTION 'You can only see your own numbers';
    END IF;
    SELECT role INTO v_role FROM "sales-pipe".profiles WHERE id = p_user;

    RETURN QUERY
    SELECT s.srv,
        count(DISTINCT o.business_id),
        count(DISTINCT o.id) FILTER (WHERE o.stage IN ('Active', 'Interested', 'Consultation') AND EXISTS (
            SELECT 1 FROM "sales-pipe".threads t WHERE t.opportunity_id = o.id AND t.status = 'Replied'
              AND t.last_inbound_at > coalesce(t.last_outbound_at, '-infinity'))),
        count(DISTINCT o.id) FILTER (WHERE o.stage IN ('Active', 'Interested', 'Consultation')),
        count(DISTINCT o.id) FILTER (WHERE o.stage = 'Won')
    FROM unnest("sales-pipe".valid_services()) WITH ORDINALITY AS s(srv, ord)
    LEFT JOIN ("sales-pipe".opportunities o JOIN "sales-pipe".businesses b ON b.id = o.business_id AND NOT b.archived)
        ON s.srv = ANY(o.services_pitched)
       AND (v_role = 'admin' OR o.assigned_sales_id = p_user OR o.assigned_consultant_id = p_user)
    GROUP BY s.srv, s.ord
    ORDER BY s.ord;
END;
$function$;
REVOKE ALL ON FUNCTION "sales-pipe"."v_service_counts"(p_user uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION "sales-pipe"."v_service_counts"(p_user uuid) TO "authenticated";
GRANT EXECUTE ON FUNCTION "sales-pipe"."v_service_counts"(p_user uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "sales-pipe".valid_services()
 RETURNS text[]
 LANGUAGE sql
 STABLE
 SET search_path TO ''
AS $function$
  SELECT coalesce(array_agg(s.name ORDER BY s.sort_order, s.name), '{}')
  FROM "sales-pipe".services s
$function$;
REVOKE ALL ON FUNCTION "sales-pipe"."valid_services"() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION "sales-pipe"."valid_services"() TO "authenticated";
GRANT EXECUTE ON FUNCTION "sales-pipe"."valid_services"() TO "service_role";

-- ==============================================================================
-- 5. Views
-- ==============================================================================
CREATE OR REPLACE VIEW "sales-pipe"."customer_lead_counts" WITH (security_invoker=true) AS
SELECT business_id,
    count(*)::integer AS total,
    count(*) FILTER (WHERE is_ready AND NOT do_not_contact)::integer AS ready,
    count(*) FILTER (WHERE NOT is_ready AND NOT do_not_contact)::integer AS missing,
    count(*) FILTER (WHERE do_not_contact)::integer AS do_not_contact,
    count(*) FILTER (WHERE (whatsapp_status = ANY (ARRAY['likely'::text, 'confirmed'::text])) AND NOT do_not_contact)::integer AS whatsapp,
    0 AS test,
    max(created_at) AS last_added_at
   FROM "sales-pipe".customer_leads
  GROUP BY business_id;
GRANT INSERT, SELECT, UPDATE, DELETE, MAINTAIN ON "sales-pipe"."customer_lead_counts" TO "authenticated";
GRANT INSERT, SELECT, UPDATE, DELETE, TRUNCATE, REFERENCES, TRIGGER, MAINTAIN ON "sales-pipe"."customer_lead_counts" TO "service_role";

