-- ==============================================================================
-- 9. Triggers
-- ==============================================================================
CREATE TRIGGER trg_bus_normalise BEFORE INSERT OR UPDATE OF phone, email ON "sales-pipe".businesses FOR EACH ROW EXECUTE FUNCTION "sales-pipe".trg_normalise_business_contact();
CREATE TRIGGER trg_bus_updated_at BEFORE UPDATE ON "sales-pipe".businesses FOR EACH ROW EXECUTE FUNCTION "sales-pipe".update_updated_at_column();
CREATE TRIGGER trg_businesses_compute_problems BEFORE INSERT OR UPDATE ON "sales-pipe".businesses FOR EACH ROW EXECUTE FUNCTION "sales-pipe".trg_businesses_compute_problems();
CREATE TRIGGER trg_businesses_reset_email_check BEFORE UPDATE OF email ON "sales-pipe".businesses FOR EACH ROW EXECUTE FUNCTION "sales-pipe".reset_email_check();
CREATE TRIGGER trg_generate_business_code BEFORE INSERT ON "sales-pipe".businesses FOR EACH ROW EXECUTE FUNCTION "sales-pipe".generate_business_code();
CREATE TRIGGER trg_audience_whatsapp_result AFTER UPDATE OF delivery_status, status, error_detail ON "sales-pipe".campaign_recipients FOR EACH ROW WHEN (((new.customer_lead_id IS NOT NULL) AND (new.channel = 'whatsapp'::text))) EXECUTE FUNCTION "sales-pipe".trg_audience_whatsapp_result();
CREATE TRIGGER trg_campaign_replies_intent BEFORE INSERT OR UPDATE OF body, subject ON "sales-pipe".campaign_replies FOR EACH ROW EXECUTE FUNCTION "sales-pipe".set_reply_intent();
CREATE TRIGGER trg_campaign_reply_stop_opt_out AFTER INSERT ON "sales-pipe".campaign_replies FOR EACH ROW WHEN ("sales-pipe".is_stop_reply(new.body)) EXECUTE FUNCTION "sales-pipe".trg_campaign_reply_stop_opt_out();
CREATE TRIGGER trg_booking_match BEFORE INSERT ON "sales-pipe".consultation_bookings FOR EACH ROW EXECUTE FUNCTION "sales-pipe".trg_match_booking();
CREATE TRIGGER customer_leads_touch BEFORE UPDATE ON "sales-pipe".customer_leads FOR EACH ROW EXECUTE FUNCTION "sales-pipe".customer_leads_touch();
CREATE TRIGGER trg_customer_leads_reset_email_check BEFORE UPDATE OF email ON "sales-pipe".customer_leads FOR EACH ROW EXECUTE FUNCTION "sales-pipe".reset_email_check();
CREATE TRIGGER trg_message_stop_opt_out AFTER INSERT ON "sales-pipe".messages FOR EACH ROW WHEN (((new.direction = 'inbound'::text) AND "sales-pipe".is_stop_reply(new.body))) EXECUTE FUNCTION "sales-pipe".trg_message_stop_opt_out();
CREATE TRIGGER trg_messages_reply_intent BEFORE INSERT OR UPDATE OF body, subject ON "sales-pipe".messages FOR EACH ROW EXECUTE FUNCTION "sales-pipe".set_reply_intent();
CREATE TRIGGER trg_messages_thread_reply_intent AFTER INSERT ON "sales-pipe".messages FOR EACH ROW EXECUTE FUNCTION "sales-pipe".set_thread_reply_intent();
CREATE TRIGGER meta_templates_touch BEFORE UPDATE ON "sales-pipe".meta_templates FOR EACH ROW EXECUTE FUNCTION "sales-pipe".meta_templates_touch();
CREATE TRIGGER trg_notification_text BEFORE INSERT ON "sales-pipe".notifications FOR EACH ROW EXECUTE FUNCTION "sales-pipe".trg_notification_text();
CREATE TRIGGER trg_notifications_sync_read_to_shared AFTER UPDATE OF is_read ON "sales-pipe".notifications FOR EACH ROW EXECUTE FUNCTION "sales-pipe".trg_sync_read_to_shared_product_notifications();
CREATE TRIGGER trg_notifications_sync_to_shared AFTER INSERT ON "sales-pipe".notifications FOR EACH ROW EXECUTE FUNCTION "sales-pipe".trg_sync_to_shared_product_notifications();
CREATE CONSTRAINT TRIGGER assign_open_pitch_on_insert AFTER INSERT ON "sales-pipe".opportunities DEFERRABLE INITIALLY DEFERRED FOR EACH ROW WHEN (((new.stage = ANY (ARRAY['Active'::text, 'Interested'::text])) AND (new.assigned_sales_id IS NULL))) EXECUTE FUNCTION "sales-pipe".trg_assign_open_pitch();
CREATE CONSTRAINT TRIGGER assign_open_pitch_on_stage AFTER UPDATE OF stage ON "sales-pipe".opportunities DEFERRABLE INITIALLY DEFERRED FOR EACH ROW WHEN (((new.stage = ANY (ARRAY['Active'::text, 'Interested'::text])) AND (new.assigned_sales_id IS NULL) AND (old.stage IS DISTINCT FROM new.stage))) EXECUTE FUNCTION "sales-pipe".trg_assign_open_pitch();
CREATE TRIGGER trg_audience_won_change AFTER UPDATE OF stage ON "sales-pipe".opportunities FOR EACH ROW WHEN (((old.stage = 'Won'::text) IS DISTINCT FROM (new.stage = 'Won'::text))) EXECUTE FUNCTION "sales-pipe".trg_audience_won_change();
CREATE TRIGGER trg_dnc_stage_opt_out AFTER INSERT OR UPDATE OF stage ON "sales-pipe".opportunities FOR EACH ROW EXECUTE FUNCTION "sales-pipe".trg_dnc_stage_opt_out();
CREATE TRIGGER trg_generate_opp_code BEFORE INSERT ON "sales-pipe".opportunities FOR EACH ROW EXECUTE FUNCTION "sales-pipe".generate_opportunity_code();
CREATE TRIGGER trg_opp_reopen AFTER UPDATE OF stage ON "sales-pipe".opportunities FOR EACH ROW WHEN (((old.stage = ANY (ARRAY['Went cold'::text, 'No response'::text, 'Declined'::text, 'Do not contact'::text])) AND (new.stage = ANY (ARRAY['Active'::text, 'Interested'::text])))) EXECUTE FUNCTION "sales-pipe".trg_opp_reopen();
CREATE TRIGGER trg_opp_services_recompute_problems AFTER INSERT OR UPDATE OF services_pitched ON "sales-pipe".opportunities FOR EACH ROW EXECUTE FUNCTION "sales-pipe".trg_opp_services_recompute_problems();
CREATE TRIGGER trg_opp_stage_cleanup AFTER UPDATE OF stage ON "sales-pipe".opportunities FOR EACH ROW EXECUTE FUNCTION "sales-pipe".trg_opp_stage_cleanup();
CREATE TRIGGER trg_opps_updated_at BEFORE UPDATE ON "sales-pipe".opportunities FOR EACH ROW EXECUTE FUNCTION "sales-pipe".update_updated_at_column();
CREATE TRIGGER trg_won_adds_audience_client AFTER INSERT OR UPDATE OF stage ON "sales-pipe".opportunities FOR EACH ROW WHEN ((new.stage = 'Won'::text)) EXECUTE FUNCTION "sales-pipe".trg_won_adds_audience_client();

-- ==============================================================================
-- 10. Row level security
-- ==============================================================================
ALTER TABLE "sales-pipe"."app_logs" ENABLE ROW LEVEL SECURITY;
CREATE POLICY "app_logs_admin" ON "sales-pipe"."app_logs" AS PERMISSIVE FOR ALL TO "authenticated"
    USING (("sales-pipe".get_user_role() = 'admin'::text))
    WITH CHECK (("sales-pipe".get_user_role() = 'admin'::text));
ALTER TABLE "sales-pipe"."audience_clients" ENABLE ROW LEVEL SECURITY;
CREATE POLICY "audience_clients_read" ON "sales-pipe"."audience_clients" AS PERMISSIVE FOR SELECT TO "authenticated"
    USING (("sales-pipe".get_user_role() = ANY (ARRAY['admin'::text, 'sales'::text, 'sales_consultant'::text])));
ALTER TABLE "sales-pipe"."business_categories" ENABLE ROW LEVEL SECURITY;
CREATE POLICY "business_categories_read" ON "sales-pipe"."business_categories" AS PERMISSIVE FOR SELECT TO "authenticated"
    USING (("sales-pipe".get_user_role() IS NOT NULL));
ALTER TABLE "sales-pipe"."businesses" ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Businesses read" ON "sales-pipe"."businesses" AS PERMISSIVE FOR SELECT TO PUBLIC
    USING ("sales-pipe".can_see_business(id));
CREATE POLICY "Businesses update" ON "sales-pipe"."businesses" AS PERMISSIVE FOR UPDATE TO PUBLIC
    USING ("sales-pipe".can_see_business(id))
    WITH CHECK ("sales-pipe".can_see_business(id));
ALTER TABLE "sales-pipe"."cadence_rules" ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Cadence read" ON "sales-pipe"."cadence_rules" AS PERMISSIVE FOR SELECT TO PUBLIC
    USING ((auth.role() = 'authenticated'::text));
ALTER TABLE "sales-pipe"."campaign_recipients" ENABLE ROW LEVEL SECURITY;
CREATE POLICY "campaign_recipients_read" ON "sales-pipe"."campaign_recipients" AS PERMISSIVE FOR SELECT TO "authenticated"
    USING (("sales-pipe".get_user_role() IS NOT NULL));
ALTER TABLE "sales-pipe"."campaign_replies" ENABLE ROW LEVEL SECURITY;
CREATE POLICY "campaign_replies_read" ON "sales-pipe"."campaign_replies" AS PERMISSIVE FOR SELECT TO PUBLIC
    USING (("sales-pipe".get_user_role() = ANY (ARRAY['admin'::text, 'sales'::text, 'sales_consultant'::text, 'consultant'::text])));
ALTER TABLE "sales-pipe"."consultation_bookings" ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Consultation bookings read admin" ON "sales-pipe"."consultation_bookings" AS PERMISSIVE FOR SELECT TO PUBLIC
    USING (("sales-pipe".get_user_role() = 'admin'::text));
CREATE POLICY "Consultation bookings read sales" ON "sales-pipe"."consultation_bookings" AS PERMISSIVE FOR SELECT TO PUBLIC
    USING ((EXISTS ( SELECT 1
   FROM "sales-pipe".opportunities o
  WHERE ((o.id = consultation_bookings.matched_opportunity_id) AND ((o.assigned_sales_id = auth.uid()) OR (o.assigned_consultant_id = auth.uid()))))));
CREATE POLICY "Consultation bookings update admin" ON "sales-pipe"."consultation_bookings" AS PERMISSIVE FOR UPDATE TO PUBLIC
    USING (("sales-pipe".get_user_role() = 'admin'::text));
ALTER TABLE "sales-pipe"."customer_import_batches" ENABLE ROW LEVEL SECURITY;
CREATE POLICY "customer_import_batches_access" ON "sales-pipe"."customer_import_batches" AS PERMISSIVE FOR ALL TO "authenticated"
    USING (("sales-pipe".get_user_role() = ANY (ARRAY['admin'::text, 'sales'::text, 'sales_consultant'::text])))
    WITH CHECK (("sales-pipe".get_user_role() = ANY (ARRAY['admin'::text, 'sales'::text, 'sales_consultant'::text])));
ALTER TABLE "sales-pipe"."customer_leads" ENABLE ROW LEVEL SECURITY;
CREATE POLICY "customer_leads_access" ON "sales-pipe"."customer_leads" AS PERMISSIVE FOR ALL TO "authenticated"
    USING (("sales-pipe".get_user_role() = ANY (ARRAY['admin'::text, 'sales'::text, 'sales_consultant'::text])))
    WITH CHECK (("sales-pipe".get_user_role() = ANY (ARRAY['admin'::text, 'sales'::text, 'sales_consultant'::text])));
ALTER TABLE "sales-pipe"."drafts" ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Drafts read" ON "sales-pipe"."drafts" AS PERMISSIVE FOR SELECT TO PUBLIC
    USING ((EXISTS ( SELECT 1
   FROM "sales-pipe".threads t
  WHERE (t.id = drafts.thread_id))));
ALTER TABLE "sales-pipe"."email_campaigns" ENABLE ROW LEVEL SECURITY;
CREATE POLICY "email_campaigns_access" ON "sales-pipe"."email_campaigns" AS PERMISSIVE FOR ALL TO PUBLIC
    USING ((COALESCE("sales-pipe".get_user_role(), ''::text) = ANY (ARRAY['admin'::text, 'sales'::text, 'sales_consultant'::text])))
    WITH CHECK ((COALESCE("sales-pipe".get_user_role(), ''::text) = ANY (ARRAY['admin'::text, 'sales'::text, 'sales_consultant'::text])));
ALTER TABLE "sales-pipe"."email_databases" ENABLE ROW LEVEL SECURITY;
CREATE POLICY "email_databases_access" ON "sales-pipe"."email_databases" AS PERMISSIVE FOR ALL TO PUBLIC
