    WITH CHECK ((COALESCE("sales-pipe".get_user_role(), ''::text) = ANY (ARRAY['admin'::text, 'sales'::text, 'sales_consultant'::text])));
ALTER TABLE "sales-pipe"."error_logs" ENABLE ROW LEVEL SECURITY;
