   FROM "sales-pipe".threads t
  WHERE (t.id = messages.thread_id))));
ALTER TABLE "sales-pipe"."meta_templates" ENABLE ROW LEVEL SECURITY;
CREATE POLICY "meta_templates_read" ON "sales-pipe"."meta_templates" AS PERMISSIVE FOR SELECT TO "authenticated"
    USING (("sales-pipe".get_user_role() IS NOT NULL));
ALTER TABLE "sales-pipe"."notes" ENABLE ROW LEVEL SECURITY;
