ALTER TABLE "sales-pipe"."opportunities" ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Opportunities read" ON "sales-pipe"."opportunities" AS PERMISSIVE FOR SELECT TO PUBLIC
    USING (((auth.role() = 'authenticated'::text) AND (("sales-pipe".get_user_role() = 'admin'::text) OR (assigned_sales_id = auth.uid()) OR (assigned_consultant_id = auth.uid()) OR ((assigned_sales_id IS NULL) AND (assigned_consultant_id IS NULL)))));
ALTER TABLE "sales-pipe"."opt_outs" ENABLE ROW LEVEL SECURITY;
CREATE POLICY "opt_outs_read" ON "sales-pipe"."opt_outs" AS PERMISSIVE FOR SELECT TO "authenticated"
    USING (("sales-pipe".get_user_role() IS NOT NULL));
ALTER TABLE "sales-pipe"."outreach_platforms" ENABLE ROW LEVEL SECURITY;
CREATE POLICY "outreach_platforms_read" ON "sales-pipe"."outreach_platforms" AS PERMISSIVE FOR SELECT TO "authenticated"
    USING (("sales-pipe".get_user_role() IS NOT NULL));
ALTER TABLE "sales-pipe"."profiles" ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Profiles read" ON "sales-pipe"."profiles" AS PERMISSIVE FOR SELECT TO PUBLIC
    USING ((auth.role() = 'authenticated'::text));
ALTER TABLE "sales-pipe"."services" ENABLE ROW LEVEL SECURITY;
CREATE POLICY "services_read" ON "sales-pipe"."services" AS PERMISSIVE FOR SELECT TO "authenticated"
    USING (("sales-pipe".get_user_role() IS NOT NULL));
ALTER TABLE "sales-pipe"."settings" ENABLE ROW LEVEL SECURITY;
CREATE POLICY "settings_admin_manage" ON "sales-pipe"."settings" AS PERMISSIVE FOR ALL TO "authenticated"
    USING (("sales-pipe".get_user_role() = 'admin'::text))
    WITH CHECK (("sales-pipe".get_user_role() = 'admin'::text));
CREATE POLICY "settings_read" ON "sales-pipe"."settings" AS PERMISSIVE FOR SELECT TO "authenticated"
    USING (true);
ALTER TABLE "sales-pipe"."stage_changes" ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Stage changes read" ON "sales-pipe"."stage_changes" AS PERMISSIVE FOR SELECT TO PUBLIC
    USING ((EXISTS ( SELECT 1
   FROM "sales-pipe".opportunities o
  WHERE (o.id = stage_changes.opportunity_id))));
ALTER TABLE "sales-pipe"."tasks" ENABLE ROW LEVEL SECURITY;
CREATE POLICY "tasks_staff" ON "sales-pipe"."tasks" AS PERMISSIVE FOR ALL TO "authenticated"
    USING (("sales-pipe".get_user_role() IS NOT NULL))
    WITH CHECK (("sales-pipe".get_user_role() IS NOT NULL));
ALTER TABLE "sales-pipe"."templates" ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Templates read" ON "sales-pipe"."templates" AS PERMISSIVE FOR SELECT TO PUBLIC
    USING ((auth.role() = 'authenticated'::text));
ALTER TABLE "sales-pipe"."threads" ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Threads read" ON "sales-pipe"."threads" AS PERMISSIVE FOR SELECT TO PUBLIC
    USING ((EXISTS ( SELECT 1
   FROM "sales-pipe".opportunities o
  WHERE (o.id = threads.opportunity_id))));
ALTER TABLE "sales-pipe"."user_logs" ENABLE ROW LEVEL SECURITY;
CREATE POLICY "user_logs_admin" ON "sales-pipe"."user_logs" AS PERMISSIVE FOR ALL TO "authenticated"
    USING (("sales-pipe".get_user_role() = 'admin'::text))
    WITH CHECK (("sales-pipe".get_user_role() = 'admin'::text));
